// MCP tools for batch 69 (3-Nov-2026): ribbon banners, cross-stitch sizing, mockup print areas.
// The pure cores come from src/tools_core69.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// xstitch-core-69c.js, ribbon-core-69c.js, mockup-core-69.js) — one source of truth with the /tools/ pages
// ribbon-banner, cross-stitch-pattern-maker and the t-shirt / hoodie / tote-bag / mug / poster / billboard mockups. Stateless: no D1/R2, no fetch.
import { MGD69C, MGD69M as MK } from "./tools_core69.js";
import { PRODUCTS73 } from "./mcp_tools73.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const fin = (v) => Number.isFinite(num(v));
const r1 = (v) => Math.round(v * 10) / 10;
const r2 = (v) => Math.round(v * 100) / 100;
const HEX = /^#[0-9a-f]{6}$/i;
const RB = MGD69C.rb, XS = MGD69C.xs;
const SHAPES = RB.SHAPES.map((s) => s[0]);
const ENDS = RB.ENDS.map((s) => s[0]);
const PRESETS = RB.PRESETS.map((p) => p[0]);
const FABRICS = XS.FABRICS.map((f) => f[0]);
const PRODUCTS = ["tshirt", "hoodie", "tote", "mug", "poster", "billboard"];
const MOCK_PAGES = { tshirt: "t-shirt-mockup", hoodie: "hoodie-mockup", tote: "tote-bag-mockup", mug: "mug-mockup", poster: "poster-mockup", billboard: "billboard-mockup" };

