export const NEXT69 = {
  make_ribbon_banner: "Next step: open the ribbon banner link to set your own font, see every preset and download SVG or transparent PNG.",
  calc_cross_stitch: "Next step: open the cross-stitch pattern maker link to turn a photo into a chart with symbols, a thread key and a printable PDF.",
  get_mockup_print_area: "Next step: open the mockup link to place your design on the product and download a high-resolution mockup.",
};

// ---- ribbon banner
function ribbon(a) {
  if (a.shape !== undefined && !SHAPES.includes(a.shape)) return err("shape must be one of: " + SHAPES.join(", ") + ".");
  if (a.end !== undefined && !ENDS.includes(a.end)) return err("end must be one of: " + ENDS.join(", ") + ".");
  if (a.preset !== undefined && !PRESETS.includes(a.preset)) return err("preset must be one of: " + PRESETS.join(", ") + ".");
  for (const k of ["color", "text_color"]) if (a[k] !== undefined && !HEX.test(String(a[k]))) return err(k + " must be #rrggbb.");
  for (const k of ["text", "text2"]) if (typeof a[k] === "string" && a[k].length > 60) return err(k + " must be at most 60 characters.");
  if (a.width !== undefined && !(fin(a.width) && num(a.width) >= 120 && num(a.width) <= 4000)) return err("width must be 120-4000 px.");
  if (a.height !== undefined && !(fin(a.height) && num(a.height) >= 20 && num(a.height) <= 600)) return err("height must be 20-600 px.");
  if (a.bend !== undefined && !(fin(a.bend) && num(a.bend) >= 0 && num(a.bend) <= 0.6)) return err("bend must be 0-0.6.");
  const p = RB.PRESETS.find((x) => x[0] === (a.preset || "red"));
  const o = { color: a.color || p[2], textColor: a.text_color || p[3] };
  if (a.shape) o.shape = a.shape;
  if (a.end) o.end = a.end;
  if (fin(a.width)) o.width = num(a.width);
  if (fin(a.height)) o.height = num(a.height);
  if (fin(a.bend)) o.bend = num(a.bend);
  if (typeof a.text === "string") o.text = str(a.text, 60);
  if (typeof a.text2 === "string") o.text2 = str(a.text2, 60);
  if (a.font === "sans") o.font = "sans";
  if (typeof a.uppercase === "boolean") o.upper = a.uppercase;
  if (typeof a.stitch === "boolean") o.stitch = a.stitch;
  const r = RB.build(o), page = `${T}/ribbon-banner/`, end = RB.ENDS.find((s) => s[0] === r.o.end);
  const fit = r.fit.map((f) => ({ font_size: r1(f.size), fits: !!f.fits }));
  const svg = RB.svg(r, { title: (r.o.text || "Ribbon banner").slice(0, 60) });
  const lines = [`**Ribbon banner (${r.o.shape}, ${end[1].toLowerCase()} ends): ${r1(r.W)} × ${r1(r.H)} px; text ${fit.map((f) => `${f.font_size} px${f.fits ? "" : " (too long for the band, shorten it or widen the ribbon)"}`).join(" and ")}.**`];
  const sc = { shape: r.o.shape, end: r.o.end, width: r1(r.W), height: r1(r.H), color: r.o.color, text_color: r.o.textColor, text_fit: fit, page };
  if (svg.length <= OUT_CAP) { lines.push(`SVG (${Math.round(svg.length / 1024)} KB, text on a path so it stays editable; the font falls back to Georgia / Arial):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The SVG is too large to return inline: download it from the page."); sc.svg_too_large = true; }
  lines.push("Own font, every preset, SVG and transparent PNG: " + page);
  return ok(lines.join("\n"), sc);
}

// ---- cross stitch
function xstitch(a) {
  if (a.fabric !== undefined && !FABRICS.includes(a.fabric)) return err("fabric must be one of: " + FABRICS.join(", ") + ".");
  const pos = (k, max) => a[k] === undefined || (fin(a[k]) && num(a[k]) > 0 && num(a[k]) <= max);
  if (!pos("cols", 2000) || !pos("rows", 2000)) return err("cols and rows must be 1-2000 stitches.");
  if (!pos("width", 200) || !pos("height", 200)) return err("width and height must be positive (up to 200).");
  if (a.margin !== undefined && !(fin(a.margin) && num(a.margin) >= 0 && num(a.margin) <= 12)) return err("margin must be 0-12 inches.");
  if (a.strands !== undefined && !(Number.isInteger(num(a.strands)) && num(a.strands) >= 1 && num(a.strands) <= 6)) return err("strands must be a whole number 1-6.");
  if (a.cols === undefined && a.width === undefined) return err("Give cols (stitches across) or width (finished size).");
  const unit = a.unit === "cm" ? "cm" : "in";
  const p = XS.plan({ cols: fin(a.cols) ? num(a.cols) : undefined, rows: fin(a.rows) ? num(a.rows) : undefined, width: fin(a.width) ? num(a.width) : undefined, height: fin(a.height) ? num(a.height) : undefined,
    unit, fabric: a.fabric || "aida14", margin: fin(a.margin) ? num(a.margin) : undefined, strands: fin(a.strands) ? num(a.strands) : undefined });
  const z = p.size, page = `${T}/cross-stitch-pattern-maker/`;
  const lines = [`**${p.cols} × ${p.rows} stitches on ${p.fabric}, ${z.spi} stitches per inch: finished ${z.inW} × ${z.inH} in (${z.cmW} × ${z.cmH} cm); cut the fabric ${z.cutInW} × ${z.cutInH} in (${z.cutCmW} × ${z.cutCmH} cm) with ${z.margin} in spare each side.**`,
    `Use ${p.strands} strand${p.strands > 1 ? "s" : ""} of 6-strand floss; one 8 m skein covers about ${p.stitchesPerSkein} full crosses (with 20% waste), so a solid ${p.cols * p.rows}-stitch design in one colour would need ${p.skeinsIfAllOneColour} skein${p.skeinsIfAllOneColour > 1 ? "s" : ""}.`,
    "Same design on other fabrics: " + p.all.map((f) => `${f.fabric} ${f.inW} × ${f.inH} in`).join("; ") + ".",
    "Photo to chart with symbols, thread key and PDF: " + page];
  return ok(lines.join("\n"), { cols: p.cols, rows: p.rows, fabric: p.fabric, stitches_per_inch: z.spi, finished_in: [z.inW, z.inH], finished_cm: [z.cmW, z.cmH], cut_in: [z.cutInW, z.cutInH], cut_cm: [z.cutCmW, z.cutCmH], margin_in: z.margin,
    strands: p.strands, stitches_per_skein: p.stitchesPerSkein, skeins_if_one_colour: p.skeinsIfAllOneColour, other_fabrics: p.all, page });
}

// ---- mockup print areas
const inRow = (label, w, h, dpi, extra, px0) => { const px = px0 || (dpi ? MK.printPx(w, h, dpi) : null); return Object.assign({ name: label, in: [r2(w), r2(h)], cm: [r2(w * 2.54), r2(h * 2.54)], px }, extra || {}); };
function mockup(a) {
  // 7-Nov-2026: list the b73 products too (index.js routes those to mcp_tools73.js before this runs)
  if (!PRODUCTS.includes(a.product)) return err("product must be one of: " + PRODUCTS.concat(PRODUCTS73).join(", ") + ".");
  if (a.dpi !== undefined && !(fin(a.dpi) && num(a.dpi) >= 72 && num(a.dpi) <= 1200)) return err("dpi must be 72-1200.");
  const pr = a.product, page = `${T}/${MOCK_PAGES[pr]}/`, dpi = fin(a.dpi) ? Math.round(num(a.dpi)) : pr === "billboard" ? null : 300;
  const pick = (table, key) => { if (key === undefined) return Object.keys(table); if (!(key in table)) return null; return [key]; };
  let rows = [], notes = [];
  if (pr === "tshirt" || pr === "hoodie") {
    const A = pr === "tshirt" ? MK.TEE_AREAS : MK.HOOD_AREAS, keys = pick(A, a.area);
    if (!keys) return err("area must be one of: " + Object.keys(A).join(", ") + ".");
    rows = keys.map((k) => inRow(k, A[k][0], A[k][1], dpi, { below_collar_in: A[k][2] }));
    notes.push("Typical adult sizes; small and youth garments take smaller areas. Top of the print sits the given inches below the collar seam.");
  } else if (pr === "tote") {
    if (a.style !== undefined && !(a.style in MK.TOTE)) return err("style must be standard or wide.");
    const bag = MK.TOTE[a.style || "standard"], keys = pick(MK.TOTE_AREAS, a.area);
    if (!keys) return err("area must be one of: " + Object.keys(MK.TOTE_AREAS).join(", ") + ".");
    rows = keys.map((k) => { const s = Math.min(MK.TOTE_AREAS[k], bag.w - 3); return inRow(k, s, s, dpi); });
    notes.push(`On the ${a.style || "standard"} tote (${bag.w} × ${bag.h} in), keeping 1.5 in clear of the side seams.`);
  } else if (pr === "mug") {
    const keys = pick(MK.MUGS, a.size === undefined ? undefined : String(a.size));
    if (!keys) return err("size must be 11 or 15 (oz).");
    rows = keys.map((k) => { const m = MK.mugWrap(k, dpi); return inRow(`${k} oz wrap`, m.wrap_in[0], m.wrap_in[1], dpi, { mug_mm: { diameter: m.diameter_mm, height: m.height_mm, circumference: m.circumference_mm }, handle_gap_in: m.handle_gap_in }, m.wrap_px); });
    notes.push("Typical sublimation blanks; the wrap leaves a gap at the handle. Check your blank's own template before printing.");
  } else if (pr === "poster") {
    const keys = pick(MK.POSTERS, a.size);
    if (!keys) return err("size must be one of: " + Object.keys(MK.POSTERS).join(", ") + ".");
    rows = keys.map((k) => { const p = MK.POSTERS[k], f = p[2] === "mm" ? 1 / 25.4 : 1; return inRow(k, p[0] * f, p[1] * f, dpi, p[2] === "mm" ? { mm: [p[0], p[1]] } : {}); });
    notes.push("Trim sizes (portrait); add bleed if the printer asks for it.");
  } else {
    const keys = pick(MK.BILLBOARDS, a.size);
    if (!keys) return err("size must be one of: " + Object.keys(MK.BILLBOARDS).join(", ") + ".");
    rows = keys.map((k) => { const b = MK.BILLBOARDS[k]; return inRow(b[2], b[0] * 12, b[1] * 12, dpi, { key: k, ft: [r2(b[0]), r2(b[1])], m: [r2(b[0] * 0.3048), r2(b[1] * 0.3048)] }); });
    notes.push("Typical US out-of-home sizes (visible area). Large-format files are usually built at a reduced scale: ask the vendor for their spec and dpi.");
  }
  const fmt = (r) => `${r.name}: ${r.ft ? `${r.ft[0]} × ${r.ft[1]} ft (${r.m[0]} × ${r.m[1]} m)` : `${r.in[0]} × ${r.in[1]} in (${r.cm[0]} × ${r.cm[1]} cm)`}${r.px ? `, ${r.px[0]} × ${r.px[1]} px at ${dpi} dpi` : ""}${r.below_collar_in ? `, ${r.below_collar_in} in below the collar` : ""}${r.handle_gap_in ? `, ${r.handle_gap_in} in handle gap` : ""}`;
  const lines = [`**${pr === "tshirt" ? "T-shirt" : pr[0].toUpperCase() + pr.slice(1)} print area${rows.length > 1 ? "s" : ""}:**`].concat(rows.map((r) => "- " + fmt(r)), notes, "Place your design on the product and download the mockup: " + page);
  return ok(lines.join("\n"), { product: pr, dpi, areas: rows, page });
}

const HANDLERS = { make_ribbon_banner: ribbon, calc_cross_stitch: xstitch, get_mockup_print_area: mockup };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools69Tool(name) { return NAMES.has(name); }
export async function callTools69Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
